const SOFTBALL_RECOVERED_LESSONS=[{"text":"The Talk A Bee pitcher is on the mound with the softball ready to throw.","translations":{"es":"La abeja de Talk A Bee está en el montículo con la pelota lista para lanzar.","fr":"L'abeille Talk A Bee est sur le monticule avec la balle prête à lancer.","de":"Die Talk A Bee Biene steht als Pitcher auf dem Hügel und hält den Softball bereit.","it":"L'ape Talk A Bee è sulla pedana con la palla pronta da lanciare.","pt":"A abelha Talk A Bee está no monte com a bola pronta para arremessar.","no":"Talk A Bee-bien står på pitcherhaugen med softballen klar til kast."}},{"text":"The pitcher steps forward and sends the ball toward home plate.","translations":{"es":"La lanzadora da un paso adelante y envía la pelota hacia el plato de home.","fr":"La lanceuse avance et envoie la balle vers le marbre.","de":"Der Pitcher macht einen Schritt nach vorn und wirft den Ball zur Home Plate.","it":"La lanciatrice fa un passo avanti e manda la palla verso casa base.","pt":"A arremessadora avança e manda a bola em direção à base principal.","no":"Pitcheren går frem og sender ballen mot hjemmeplaten."}},{"text":"The batter watches the pitcher and gets ready to swing.","translations":{"es":"La bateadora observa a la lanzadora y se prepara para batear.","fr":"La frappeuse regarde la lanceuse et se prépare à frapper.","de":"Die Schlagfrau beobachtet den Pitcher und macht sich zum Schlag bereit.","it":"La battitrice guarda la lanciatrice e si prepara a colpire.","pt":"A rebatedora observa a arremessadora e se prepara para rebater.","no":"Slagspilleren følger med på pitcheren og gjør seg klar til å slå."}},{"text":"She grips the bat with both hands and keeps her eyes on the softball.","translations":{"es":"Sujeta el bate con ambas manos y mantiene la vista en la pelota.","fr":"Elle tient la batte à deux mains et garde les yeux sur la balle.","de":"Sie hält den Schläger mit beiden Händen und behält den Ball im Blick.","it":"Tiene la mazza con entrambe le mani e guarda la palla.","pt":"Ela segura o taco com as duas mãos e mantém os olhos na bola.","no":"Hun holder køllen med begge hender og følger ballen med blikket."}},{"text":"Home plate, the pitcher's mound, the infield, and the outfield are all parts of the softball field.","translations":{"es":"El plato de home, el montículo, el cuadro y los jardines forman parte del campo de sóftbol.","fr":"Le marbre, le monticule, le champ intérieur et le champ extérieur font partie du terrain de softball.","de":"Home Plate, Pitcherhügel, Innenfeld und Außenfeld gehören zum Softballfeld.","it":"Casa base, la pedana, il campo interno e quello esterno fanno parte del campo da softball.","pt":"A base principal, o monte, o campo interno e o campo externo fazem parte do campo de softball.","no":"Hjemmeplaten, pitcherhaugen, indre felt og ytre felt er deler av softballbanen."}},{"text":"Fielders spread out and get ready for the ball.","translations":{"es":"Los jugadores se colocan y se preparan para la pelota.","fr":"Les joueurs se placent et se préparent pour la balle.","de":"Die Feldspieler verteilen sich und machen sich bereit.","it":"I giocatori si dispongono e si preparano per la palla.","pt":"Os jogadores se espalham e ficam prontos para a bola.","no":"Feltspillerne sprer seg og gjør seg klare."}},{"text":"The pitcher throws, the batter swings, the catcher receives the pitch, and the umpire watches the play.","translations":{"es":"La lanzadora lanza, la bateadora batea, la receptora recibe y el árbitro observa la jugada.","fr":"La lanceuse lance, la frappeuse frappe, la receveuse attrape et l'arbitre observe le jeu.","de":"Der Pitcher wirft, die Schlagfrau schlägt, der Catcher fängt und der Schiedsrichter beobachtet das Spiel.","it":"La lanciatrice lancia, la battitrice colpisce, la ricevitrice prende la palla e l'arbitro osserva il gioco.","pt":"A arremessadora lança, a rebatedora rebate, a receptora recebe e o árbitro observa a jogada.","no":"Pitcheren kaster, slagspilleren slår, catcheren tar imot og dommeren følger spillet."}},{"text":"Every player has an important job during the game.","translations":{"es":"Cada jugador tiene un trabajo importante durante el partido.","fr":"Chaque joueur a un rôle important pendant le match.","de":"Jeder Spieler hat während des Spiels eine wichtige Aufgabe.","it":"Ogni giocatore ha un ruolo importante durante la partita.","pt":"Cada jogador tem uma função importante durante o jogo.","no":"Hver spiller har en viktig oppgave under kampen."}},{"text":"The scoreboard shows the home team, guest team, and current inning.","translations":{"es":"El marcador muestra el equipo local, el visitante y la entrada actual.","fr":"Le tableau affiche l'équipe locale, l'équipe visiteuse et la manche actuelle.","de":"Die Anzeigetafel zeigt Heimteam, Gastteam und das aktuelle Inning.","it":"Il tabellone mostra la squadra di casa, gli ospiti e l'inning corrente.","pt":"O placar mostra o time da casa, o visitante e a entrada atual.","no":"Resultattavlen viser hjemmelaget, gjestelaget og gjeldende inning."}},{"text":"Fans can look at it to follow the game.","translations":{"es":"Los aficionados pueden mirarlo para seguir el partido.","fr":"Les supporters peuvent le regarder pour suivre le match.","de":"Die Zuschauer können dort den Spielstand verfolgen.","it":"I tifosi possono guardarlo per seguire la partita.","pt":"Os torcedores podem olhar para acompanhar o jogo.","no":"Tilskuerne kan se på den for å følge kampen."}},{"text":"Spectators cheer from the bleachers behind home plate.","translations":{"es":"Los espectadores animan desde las gradas detrás del plato.","fr":"Les spectateurs encouragent depuis les tribunes derrière le marbre.","de":"Die Zuschauer jubeln von den Tribünen hinter der Home Plate.","it":"Gli spettatori fanno il tifo dalle tribune dietro casa base.","pt":"Os espectadores torcem nas arquibancadas atrás da base principal.","no":"Tilskuerne heier fra tribunene bak hjemmeplaten."}},{"text":"The lake and mountains make this a beautiful place for a softball game.","translations":{"es":"El lago y las montañas hacen de este un hermoso lugar para jugar sóftbol.","fr":"Le lac et les montagnes rendent ce terrain magnifique.","de":"Der See und die Berge machen dies zu einem wunderschönen Softballplatz.","it":"Il lago e le montagne rendono bellissimo questo campo.","pt":"O lago e as montanhas tornam este um belo lugar para jogar softball.","no":"Innsjøen og fjellene gjør dette til et vakkert sted for en softballkamp."}}];
const TRAIN_RECOVERED_LESSONS=[{"text":"I would like a ticket, please.","translations":{"es":"Quiero un billete, por favor.","fr":"Je voudrais un billet, s’il vous plaît.","de":"Ich möchte eine Fahrkarte, bitte.","it":"Vorrei un biglietto, per favore.","pt":"Quero um bilhete, por favor.","no":"Jeg vil gjerne ha en billett, takk."}},{"text":"One ticket to Naples, please.","translations":{"es":"Un billete a Nápoles, por favor.","fr":"Un billet pour Naples, s’il vous plaît.","de":"Eine Fahrkarte nach Neapel, bitte.","it":"Un biglietto per Napoli, per favore.","pt":"Um bilhete para Nápoles, por favor.","no":"En billett til Napoli, takk."}},{"text":"How much is the ticket?","translations":{"es":"¿Cuánto cuesta el billete?","fr":"Combien coûte le billet ?","de":"Wie viel kostet die Fahrkarte?","it":"Quanto costa il biglietto?","pt":"Quanto custa o bilhete?","no":"Hvor mye koster billetten?"}},{"text":"Where is platform two?","translations":{"es":"¿Dónde está el andén dos?","fr":"Où est le quai deux ?","de":"Wo ist Gleis zwei?","it":"Dov’è il binario due?","pt":"Onde fica a plataforma dois?","no":"Hvor er spor to?"}},{"text":"The train leaves from platform two.","translations":{"es":"El tren sale del andén dos.","fr":"Le train part du quai deux.","de":"Der Zug fährt von Gleis zwei ab.","it":"Il treno parte dal binario due.","pt":"O trem parte da plataforma dois.","no":"Toget går fra spor to."}},{"text":"Thank you for your help.","translations":{"es":"Gracias por su ayuda.","fr":"Merci pour votre aide.","de":"Danke für Ihre Hilfe.","it":"Grazie per il suo aiuto.","pt":"Obrigado pela sua ajuda.","no":"Takk for hjelpen."}},{"text":"What time does the train leave?","translations":{"es":"¿A qué hora sale el tren?","fr":"À quelle heure part le train ?","de":"Wann fährt der Zug ab?","it":"A che ora parte il treno?","pt":"A que horas parte o trem?","no":"Når går toget?"}},{"text":"The train leaves at 5:10.","translations":{"es":"El tren sale a las cinco y diez.","fr":"Le train part à cinq heures dix.","de":"Der Zug fährt um fünf Uhr zehn ab.","it":"Il treno parte alle cinque e dieci.","pt":"O trem parte às cinco e dez.","no":"Toget går ti over fem."}},{"text":"Does it arrive on time?","translations":{"es":"¿Llega a tiempo?","fr":"Arrive-t-il à l’heure ?","de":"Kommt er pünktlich an?","it":"Arriva in orario?","pt":"Chega a horas?","no":"Kommer det i tide?"}},{"text":"Look at the departure board.","translations":{"es":"Mire el tablero de salidas.","fr":"Regardez le tableau des départs.","de":"Schauen Sie auf die Abfahrtstafel.","it":"Guardi il tabellone delle partenze.","pt":"Olhe para o painel de partidas.","no":"Se på avgangstavlen."}},{"text":"My train goes to Sorrento.","translations":{"es":"Mi tren va a Sorrento.","fr":"Mon train va à Sorrente.","de":"Mein Zug fährt nach Sorrent.","it":"Il mio treno va a Sorrento.","pt":"O meu trem vai para Sorrento.","no":"Toget mitt går til Sorrento."}},{"text":"The train is on time.","translations":{"es":"El tren está a tiempo.","fr":"Le train est à l’heure.","de":"Der Zug ist pünktlich.","it":"Il treno è in orario.","pt":"O trem está a horas.","no":"Toget er i rute."}},{"text":"This is my suitcase.","translations":{"es":"Esta es mi maleta.","fr":"Voici ma valise.","de":"Das ist mein Koffer.","it":"Questa è la mia valigia.","pt":"Esta é a minha mala.","no":"Dette er kofferten min."}},{"text":"I have a backpack.","translations":{"es":"Tengo una mochila.","fr":"J’ai un sac à dos.","de":"Ich habe einen Rucksack.","it":"Ho uno zaino.","pt":"Tenho uma mochila.","no":"Jeg har en ryggsekk."}},{"text":"Where do I put my luggage?","translations":{"es":"¿Dónde pongo mi equipaje?","fr":"Où dois-je mettre mes bagages ?","de":"Wo stelle ich mein Gepäck hin?","it":"Dove metto il mio bagaglio?","pt":"Onde coloco a minha bagagem?","no":"Hvor skal jeg sette bagasjen?"}},{"text":"Here is my ticket.","translations":{"es":"Aquí está mi billete.","fr":"Voici mon billet.","de":"Hier ist meine Fahrkarte.","it":"Ecco il mio biglietto.","pt":"Aqui está o meu bilhete.","no":"Her er billetten min."}},{"text":"Is this my train?","translations":{"es":"¿Es este mi tren?","fr":"Est-ce mon train ?","de":"Ist das mein Zug?","it":"È questo il mio treno?","pt":"Este é o meu trem?","no":"Er dette toget mitt?"}},{"text":"We are ready to board.","translations":{"es":"Estamos listos para subir.","fr":"Nous sommes prêts à monter.","de":"Wir sind bereit einzusteigen.","it":"Siamo pronti a salire.","pt":"Estamos prontos para embarcar.","no":"Vi er klare til å gå om bord."}}];
const JULIE_RECOVERED_LESSONS=[{"text":"Welcome to the island.","translations":{"es":"Bienvenidos a la isla.","fr":"Bienvenue sur l’île.","de":"Willkommen auf der Insel.","it":"Benvenuti sull’isola.","pt":"Bem-vindos à ilha.","no":"Velkommen til øya."}},{"text":"Hello, my name is Julie.","translations":{"es":"Hola, me llamo Julie.","fr":"Bonjour, je m’appelle Julie.","de":"Hallo, ich heiße Julie.","it":"Ciao, mi chiamo Julie.","pt":"Olá, chamo-me Julie.","no":"Hei, jeg heter Julie."}},{"text":"I am happy to see you.","translations":{"es":"Me alegra verte.","fr":"Je suis heureuse de te voir.","de":"Ich freue mich, dich zu sehen.","it":"Sono felice di vederti.","pt":"Fico feliz por te ver.","no":"Jeg er glad for å se deg."}},{"text":"Come and sit with me.","translations":{"es":"Ven y siéntate conmigo.","fr":"Viens t’asseoir avec moi.","de":"Komm und setz dich zu mir.","it":"Vieni a sederti con me.","pt":"Vem sentar-te comigo.","no":"Kom og sett deg sammen med meg."}},{"text":"We are beside the ocean.","translations":{"es":"Estamos junto al océano.","fr":"Nous sommes au bord de l’océan.","de":"Wir sind am Meer.","it":"Siamo vicino all’oceano.","pt":"Estamos junto ao oceano.","no":"Vi er ved havet."}},{"text":"The pier reaches the water.","translations":{"es":"El muelle llega hasta el agua.","fr":"Le quai s’avance jusqu’à l’eau.","de":"Der Steg reicht bis zum Wasser.","it":"Il molo arriva fino all’acqua.","pt":"O cais chega até à água.","no":"Brygga går ut til vannet."}},{"text":"The hammock is under the palm trees.","translations":{"es":"La hamaca está bajo las palmeras.","fr":"Le hamac est sous les palmiers.","de":"Die Hängematte ist unter den Palmen.","it":"L’amaca è sotto le palme.","pt":"A rede está debaixo das palmeiras.","no":"Hengekøyen er under palmene."}},{"text":"The table is full of pretty things.","translations":{"es":"La mesa está llena de cosas bonitas.","fr":"La table est pleine de jolies choses.","de":"Der Tisch ist voller schöner Dinge.","it":"Il tavolo è pieno di cose belle.","pt":"A mesa está cheia de coisas bonitas.","no":"Bordet er fullt av fine ting."}},{"text":"The dog is beside Julie.","translations":{"es":"El perro está junto a Julie.","fr":"Le chien est à côté de Julie.","de":"Der Hund ist neben Julie.","it":"Il cane è accanto a Julie.","pt":"O cão está ao lado da Julie.","no":"Hunden er ved siden av Julie."}},{"text":"The cat is sitting nearby.","translations":{"es":"El gato está sentado cerca.","fr":"Le chat est assis tout près.","de":"Die Katze sitzt in der Nähe.","it":"Il gatto è seduto qui vicino.","pt":"O gato está sentado perto.","no":"Katten sitter i nærheten."}},{"text":"The little pig is wearing a bandana.","translations":{"es":"El cerdito lleva un pañuelo.","fr":"Le petit cochon porte un bandana.","de":"Das kleine Schwein trägt ein Halstuch.","it":"Il maialino indossa una bandana.","pt":"O porquinho usa uma bandana.","no":"Den lille grisen har på seg et skjerf."}},{"text":"The animals are calm.","translations":{"es":"Los animales están tranquilos.","fr":"Les animaux sont calmes.","de":"Die Tiere sind ruhig.","it":"Gli animali sono tranquilli.","pt":"Os animais estão tranquilos.","no":"Dyrene er rolige."}},{"text":"Julie plays the guitar.","translations":{"es":"Julie toca la guitarra.","fr":"Julie joue de la guitare.","de":"Julie spielt Gitarre.","it":"Julie suona la chitarra.","pt":"Julie toca guitarra.","no":"Julie spiller gitar."}},{"text":"The guitar has many colors.","translations":{"es":"La guitarra tiene muchos colores.","fr":"La guitare a beaucoup de couleurs.","de":"Die Gitarre hat viele Farben.","it":"La chitarra ha molti colori.","pt":"A guitarra tem muitas cores.","no":"Gitaren har mange farger."}},{"text":"We sing together at sunset.","translations":{"es":"Cantamos juntos al atardecer.","fr":"Nous chantons ensemble au coucher du soleil.","de":"Wir singen bei Sonnenuntergang zusammen.","it":"Cantiamo insieme al tramonto.","pt":"Cantamos juntos ao pôr do sol.","no":"Vi synger sammen ved solnedgang."}},{"text":"The music plays beside the sea.","translations":{"es":"La música suena junto al mar.","fr":"La musique résonne au bord de la mer.","de":"Die Musik erklingt am Meer.","it":"La musica suona vicino al mare.","pt":"A música toca junto ao mar.","no":"Musikken spiller ved sjøen."}},{"text":"The flowers are very colorful.","translations":{"es":"Las flores son muy coloridas.","fr":"Les fleurs sont très colorées.","de":"Die Blumen sind sehr bunt.","it":"I fiori sono molto colorati.","pt":"As flores são muito coloridas.","no":"Blomstene er veldig fargerike."}},{"text":"The palm trees are tall.","translations":{"es":"Las palmeras son altas.","fr":"Les palmiers sont grands.","de":"Die Palmen sind hoch.","it":"Le palme sono alte.","pt":"As palmeiras são altas.","no":"Palmene er høye."}},{"text":"The ocean shines at sunset.","translations":{"es":"El océano brilla al atardecer.","fr":"L’océan brille au coucher du soleil.","de":"Das Meer glänzt bei Sonnenuntergang.","it":"L’oceano brilla al tramonto.","pt":"O oceano brilha ao pôr do sol.","no":"Havet skinner ved solnedgang."}},{"text":"There is an island in the distance.","translations":{"es":"Hay una isla a lo lejos.","fr":"Il y a une île au loin.","de":"In der Ferne liegt eine Insel.","it":"C’è un’isola in lontananza.","pt":"Há uma ilha ao longe.","no":"Det er en øy i det fjerne."}},{"text":"Julie enjoys a peaceful afternoon.","translations":{"es":"Julie disfruta de una tarde tranquila.","fr":"Julie profite d’un après-midi paisible.","de":"Julie genießt einen ruhigen Nachmittag.","it":"Julie si gode un pomeriggio tranquillo.","pt":"Julie desfruta de uma tarde tranquila.","no":"Julie nyter en rolig ettermiddag."}},{"text":"The animals rest near her.","translations":{"es":"Los animales descansan cerca de ella.","fr":"Les animaux se reposent près d’elle.","de":"Die Tiere ruhen sich in ihrer Nähe aus.","it":"Gli animali riposano vicino a lei.","pt":"Os animais descansam perto dela.","no":"Dyrene hviler i nærheten av henne."}},{"text":"A sailboat moves across the ocean.","translations":{"es":"Un velero navega por el océano.","fr":"Un voilier traverse l’océan.","de":"Ein Segelboot fährt über das Meer.","it":"Una barca a vela attraversa l’oceano.","pt":"Um veleiro atravessa o oceano.","no":"En seilbåt beveger seg over havet."}},{"text":"Everyone enjoys the music and the sunset.","translations":{"es":"Todos disfrutan de la música y la puesta de sol.","fr":"Tout le monde profite de la musique et du coucher du soleil.","de":"Alle genießen die Musik und den Sonnenuntergang.","it":"Tutti si godono la musica e il tramonto.","pt":"Todos desfrutam da música e do pôr do sol.","no":"Alle nyter musikken og solnedgangen."}}];
