// Optional, reversible word-follow experiment. Only touches the visible script line.
let tbWordFollowTimer=null,tbWordFollowRestore=null;
function tbWordFollowClear(){
 if(tbWordFollowTimer!==null){clearInterval(tbWordFollowTimer);tbWordFollowTimer=null;}
 if(tbWordFollowRestore){const {element,text}=tbWordFollowRestore;if(element?.isConnected)element.textContent=text;tbWordFollowRestore=null;}
}
function tbWordFollowStart(text,rate,estimated,audioDurationSeconds){
 tbWordFollowClear();
 const element=$('scriptText');
 if(!element||!text||mode==='discovery')return null;
 // Highlight the visible learning-language line; speech may include an extra instruction.
 if(!element.textContent.trim())return null;
 const original=element.textContent;
 const tokens=[...original.matchAll(/\S+/gu)];
 if(!tokens.length)return null;
 const spans=[];element.replaceChildren();let position=0;
 for(const match of tokens){
  element.append(document.createTextNode(original.slice(position,match.index)));
  const span=document.createElement('span');span.textContent=match[0];span.dataset.tbWordStart=String(match.index);
  element.append(span);spans.push(span);position=match.index+match[0].length;
 }
 element.append(document.createTextNode(original.slice(position)));
 tbWordFollowRestore={element,text:original};
 let active=-1;
 const show=index=>{if(index===active)return;if(spans[active]){spans[active].style.removeProperty('background');spans[active].style.removeProperty('color');spans[active].style.removeProperty('border-radius');}active=index;if(spans[index]){spans[index].style.setProperty('background','#ffeb00','important');spans[index].style.setProperty('color','#111','important');spans[index].style.setProperty('border-radius','4px','important');}};
 if(estimated){
  // Piper currently exposes no word timestamps. Approximate only; stop on audio completion.
  const weights=tokens.map(m=>Math.max(1.7,[...m[0]].length*.52));
  const total=weights.reduce((a,b)=>a+b,0);
  const duration=Number.isFinite(audioDurationSeconds)&&audioDurationSeconds>0 ? audioDurationSeconds*1000 : Math.max(650,Math.min(30000,(original.length/13.5)*1000/Math.max(.5,rate)));
  const started=performance.now();
  tbWordFollowTimer=setInterval(()=>{const fraction=Math.min(1,(performance.now()-started)/duration);let sum=0,index=weights.length-1;for(let i=0;i<weights.length;i++){sum+=weights[i]/total;if(fraction<sum){index=i;break;}}show(index);},60);
  show(0);
 }
 return {stopEstimate(){if(tbWordFollowTimer!==null){clearInterval(tbWordFollowTimer);tbWordFollowTimer=null;}},boundary(charIndex){let index=0;for(let i=0;i<tokens.length;i++){if(tokens[i].index<=charIndex)index=i;else break;}show(index);}};
}
function speak(text,slow,onend,followScript=true){
 if(!text){onend?.();return;}
 lastSpeech=text;
 lastSpeechFollowScript=followScript;
 const ticket=++browserSpeechTicket;
 tbWordFollowClear();
 if(browserSpeechTimer!==null){clearTimeout(browserSpeechTimer);browserSpeechTimer=null}
 let finished=false;
 const finish=()=>{if(finished||ticket!==browserSpeechTicket)return;finished=true;tbWordFollowClear();onend?.()};
 // Cancel the previous browser utterance before starting either voice engine.
 // Starting immediately after cancel() can clip the beginning in Firefox.
 window.speechSynthesis?.cancel();
 // Start the proven visible-word renderer directly from the button action.
 // Some Firefox voices never dispatch onstart, and Piper may not report playback start.
 const followRate=slow?.75:1;
 // Piper: highlight only when its audio actually starts, never on button click.
 // The adapter supplies the real audio duration, avoiding sentence-length drift.
 if(settings.voiceMode==='enhanced'&&typeof window.tbAdventurePiperSpeak==='function'){
  try{if(window.tbAdventurePiperSpeak(text,followRate,finish,(audioDurationSeconds)=>{
   if(followScript&&ticket===browserSpeechTicket&&!finished)tbWordFollowStart(text,followRate,true,audioDurationSeconds);
  })!==false){return}}
  catch(e){status('Piper unavailable; using browser voice')}
 }else if(settings.voiceMode==='enhanced')status('Piper adapter not connected yet; using browser voice');
 // Browser voice retains the previously working immediate start and boundaries.
 let tbWordFollowController=followScript?tbWordFollowStart(text,followRate,true):null;
 if(!('speechSynthesis'in window)){finish();return;}
 const u=new SpeechSynthesisUtterance(text);
 u.onend=finish;u.onerror=finish;
 // Firefox voices may omit word-boundary events. Start estimated following,
 // then switch to actual boundaries if the voice supplies them.
 u.onstart=()=>{if(followScript&&ticket===browserSpeechTicket)tbWordFollowController=tbWordFollowStart(text,u.rate,true)};
 u.onboundary=e=>{if(followScript&&ticket===browserSpeechTicket&&(e.name==='word'||typeof e.charIndex==='number')){tbWordFollowController?.stopEstimate();tbWordFollowController?.boundary(e.charIndex)}};
 u.lang=({en:'en-US',es:'es-ES',fr:'fr-FR',de:'de-DE',it:'it-IT',pt:'pt-PT',no:'nb-NO'})[settings.learn];
 u.rate=slow?.75:1;
 const wanted=read('talkabee-v2-voice-'+settings.learn,'');
 const available=speechSynthesis.getVoices();
 const matches=available.filter(v=>settings.learn==='no'?/^n[bo](-|_)/i.test(v.lang):v.lang.toLowerCase().split(/[-_]/)[0]===settings.learn);
 const voice=matches.find(v=>v.voiceURI===wanted)||matches.find(v=>v.default)||matches[0];
 if(voice)u.voice=voice;
 else if(available.length)status('No installed browser voice for '+(LANG[settings.learn]||settings.learn)+'; use Enhanced Piper or install a matching system voice');
 browserSpeechTimer=setTimeout(()=>{
  browserSpeechTimer=null;
  if(ticket!==browserSpeechTicket||settings.voiceMode==='enhanced')return;
  speechSynthesis.speak(u);
 },220);
}
function refreshVoices(){const s=$('voiceSelect');if(!s)return;s.style.setProperty('width','240px','important');s.style.setProperty('max-width','min(240px, 100%)','important');const voiceField=s.closest('.tb-voiceSelect');if(voiceField){voiceField.style.setProperty('width','240px','important');voiceField.style.setProperty('max-width','min(240px, 100%)','important');voiceField.style.setProperty('flex','0 1 240px','important');}const voices=speechSynthesis?.getVoices?.()||[];s.replaceChildren();const matching=voices.filter(v=>settings.learn==='no'?/^n[bo]/i.test(v.lang):v.lang.toLowerCase().startsWith(settings.learn));const none=document.createElement('option');none.value='';none.textContent='Browser default';s.append(none);for(const v of matching){const o=document.createElement('option');o.value=v.voiceURI;o.textContent=v.name.replace(/\s+-\s+[^-]*\([^)]*\)\s*$/, '').replace(/\s*\([^)]*\)\s*$/, '').trim();o.title=v.name+' ('+v.lang+')';s.append(o)}s.value=read('talkabee-v2-voice-'+settings.learn,'')}
