function moveHotspotLayer(toFront){
 if(selectedType!=='hotspot'||!selectedId)return;
 const arr=scene.hotspots,idx=arr.findIndex(h=>h.id===selectedId);
 if(idx<0)return;
 const destination=toFront?arr.length-1:0;
 if(idx===destination){status('Hotspot is already '+(toFront?'at the front.':'at the back.'));return;}
 const [item]=arr.splice(idx,1);arr.splice(destination,0,item);
 saveScene();renderScene();choose('hotspot',item.id);
 status((toFront?'Brought to front: ':'Sent to back: ')+(item.label||item.id)+'. Publish All to update the website.');
}
