const deleteLessonButton=document.createElement('button');
deleteLessonButton.id='deleteLesson';
deleteLessonButton.type='button';
deleteLessonButton.textContent='Delete selected lesson';
deleteLessonButton.style.marginLeft='6px';
$('addLesson').insertAdjacentElement('afterend',deleteLessonButton);
const updateDeleteLessonButton=()=>{deleteLessonButton.disabled=scene.lessons.length<=1};
deleteLessonButton.onclick=()=>{
 const index=Number($('lessonIndex').value);
 if(!Number.isInteger(index)||index<0||index>=scene.lessons.length||scene.lessons.length<=1)return;
 const selected=scene.lessons[index];
 if(!confirm('Delete Lesson '+(index+1)+' from '+(scene.title||sceneName)+'?\n\n'+(selected.text||'')+'\n\nOther lessons, Challenges, hotspots and sounds will remain unchanged.'))return;
 scene.lessons.splice(index,1);
 lesson=Math.max(0,Math.min(index,scene.lessons.length-1));
 saveScene();refreshLessons();syncLesson();renderCard();
 status('Lesson deleted and saved locally. Publish All Adventures to update the website.');
};
updateDeleteLessonButton();
const deleteChallengeButton=document.createElement('button');
deleteChallengeButton.id='deleteChallenge';
deleteChallengeButton.type='button';
deleteChallengeButton.textContent='Delete selected challenge';
